'use strict';
const $=id=>document.getElementById(id), colors=['#e65d70','#55c58c','#4b9de4','#a573df','#dfb95c'], roles=['Cadete','Soldado','Oficial','General','Comandante'], stages=['Avanzada de cadetes','Tropa de asalto','Guardia de élite','Jefe · batalla de cartas'], glyphs=['M8 4H24L28 9V22L16 29L4 22V9Z','M16 3L29 16L16 29L3 16Z','M7 4H25L29 16L25 28H7L3 16Z','M16 2L22 10L30 16L22 22L16 30L10 22L2 16L10 10Z','M4 10L10 16L16 5L22 16L28 10L25 27H7Z'];
const STORAGE='mc-command-v2';let s,selected=-1,busy=false,epoch=0,highlights=[],hints=[],feed=[];
function fresh(){return {version:2,level:1,round:0,hp:300,enemy:90,enemyMax:90,energy:[0,0,0,0,0],evo:0,grade:1,reactor:6,board:MC.board(),outcome:null,rank:0,previousRank:0}}
try{s=JSON.parse(localStorage.getItem(STORAGE))}catch{}if(!s||s.version!==2||s.board?.length!==49||!Array.isArray(s.energy)||s.energy.length!==5||s.round<0||s.round>3)s=fresh();
if(!Number.isInteger(s.rank))s.rank=0;if(!Number.isInteger(s.previousRank))s.previousRank=s.rank;
const maxHP=()=>300+(s.grade-1)*60, save=()=>{try{localStorage.setItem(STORAGE,JSON.stringify(s))}catch{}},sleep=ms=>new Promise(r=>setTimeout(r,ms));
function log(t){feed.unshift(t);feed=feed.slice(0,4);$('log').innerHTML=feed.map(x=>'<div>'+x+'</div>').join('')}
function status(t){$('status').textContent=t}
function icon(c){return '<svg viewBox="0 0 32 32" aria-hidden="true"><path d="'+glyphs[c]+'" fill="none" stroke="white" stroke-width="1.7" stroke-linejoin="round"/><path d="M10 13L16 17L22 13V20L16 23L10 20Z" fill="white" opacity=".8"/></svg>'}
function draw(){
$('evo').textContent=s.evo;$('level').textContent='NIVEL '+String(s.level).padStart(2,'0');$('powerLabel').textContent=roles[s.rank].toUpperCase()+' · GRADO '+s.grade;$('phaseLabel').textContent='RONDA '+(s.round+1)+' / 4';$('phaseName').textContent=stages[s.round];$('turn').textContent=s.outcome?'RONDA TERMINADA':busy?'COMBATE EN CURSO':'TU TURNO';$('turn').style.color=busy?'#f4b7c0':'#93e0cd';$('route').innerHTML=stages.map((n,i)=>'<div class="step '+(i===s.round?'active':i<s.round?'done':'')+'"><span class="num">'+(i<s.round?'✓':i+1)+'</span><div><b>'+['Cadetes','Asalto','Élite','Jefe final'][i]+'</b><small>'+(i===3?'Cartas':'Match de colores')+'</small></div></div>').join('');
$('enemyHealth').textContent=Math.max(0,s.enemy)+' / '+s.enemyMax;$('enemyBar').style.width=Math.max(0,s.enemy/s.enemyMax*100)+'%';$('enemyName').textContent=s.round===3?'COMANDANTE DEL VACÍO':'TROPA ENEMIGA · '+['CADETES','ASALTO','ÉLITE'][s.round];$('enemyArt').classList.toggle('boss',s.round===3);$('teamHealth').textContent=Math.max(0,s.hp)+' / '+maxHP();$('teamBar').style.width=Math.max(0,s.hp/maxHP()*100)+'%';$('matchWrap').hidden=s.round===3;$('finalZone').hidden=s.round!==3;$('reactor').textContent=s.reactor+' / 10';
$('board').innerHTML=s.board.map((c,i)=>'<button class="tile '+(selected===i?'selected ':'')+(highlights.includes(i)?'matched ':'')+(hints.includes(i)?'hint':'')+'" style="--color:'+colors[c]+'" aria-label="'+roles[c]+' '+['rojo','verde','azul','violeta','dorado'][c]+', fila '+(Math.floor(i/7)+1)+', columna '+(i%7+1)+'" aria-pressed="'+(selected===i)+'" '+(busy||s.outcome?'disabled':'')+' onclick="pick('+i+')">'+icon(c)+'</button>').join('');
$('squad').innerHTML=roles.map((n,i)=>{const cost=[2,2,3,3,4][i],final=s.round===3;return '<button class="soldier '+(s.energy[i]>=75?'ready ':'')+(final?'active-card':'')+'" style="--color:'+colors[i]+';--pos:'+(i*25)+'%" '+(!final||busy||s.outcome||s.reactor<cost?'disabled':'')+' onclick="playCard('+i+')" aria-label="'+n+', energía '+s.energy[i]+(final?', coste '+cost+' de reactor':'')+'"><div class="portrait"></div><b>'+n+'</b><div class="charge"><i style="width:'+s.energy[i]+'%"></i></div><small>'+s.energy[i]+' ⚡'+(final?' · '+cost+' ◈':'')+'</small></button>'}).join('');
$('guard').disabled=busy||!!s.outcome;$('hint').disabled=busy||!!s.outcome;$('upgrade').disabled=busy||s.evo<100||(!s.outcome&&!(s.round===0&&s.enemy===s.enemyMax));$('upgrade').textContent='Mejorar equipo · 100 ✧';showResult();
}
function showResult(){const o=s.outcome;$('result').hidden=!o;if(!o)return;const promoted=s.rank>s.previousRank&&o!=='lost';$('promotion').hidden=!promoted;$('oldHelmet').style.backgroundPosition=(s.previousRank*25)+'% top';$('newHelmet').style.backgroundPosition=(s.rank*25)+'% top';$('promotionName').textContent=roles[s.rank]+' MC';$('promotionCaption').textContent='ASCENSO · '+roles[s.previousRank]+' → '+roles[s.rank];$('resultTag').textContent=o==='level'?'SECTOR CONQUISTADO':o==='round'?'RONDA COMPLETADA':'MISIÓN INTERRUMPIDA';$('resultTitle').textContent=o==='level'?'¡Jefe derrotado!':o==='round'?'¡Tropa neutralizada!':'Tu equipo necesita refuerzos';$('resultText').textContent=o==='level'?'Has ganado 120 puntos de evolución. El nivel '+(s.level+1)+' está desbloqueado.':o==='round'?'+20 puntos de evolución. Conservas la energía y recuperas 45 de vida.':'Conservas tus puntos y mejoras. Reintenta este nivel con el equipo recuperado.';$('continue').textContent=o==='level'?'Entrar al nivel '+(s.level+1):o==='round'?(s.round===2?'Preparar batalla de cartas':'Siguiente ronda'):'Reintentar nivel';}
function endCheck(){if(s.enemy<=0){s.enemy=0;s.previousRank=s.rank;s.rank=Math.min(4,Math.max(s.rank,s.round+1));s.outcome=s.round===3?'level':'round';s.evo+=s.round===3?120:20;if(s.round<3)s.hp=Math.min(maxHP(),s.hp+45);log(s.round===3?'Jefe derrotado · +120 ✧ evolución':'Ronda ganada · +20 ✧ evolución');return true}if(s.hp<=0){s.hp=0;s.outcome='lost';log('La tropa ha caído. Puedes reintentar el nivel.');return true}return false}
async function resolve(player,token){let g=MC.groups(s.board),chain=0,total=0;while(g.length&&chain<12){if(token!==epoch)return false;highlights=g.flatMap(x=>x.cells);draw();await sleep(230);if(token!==epoch)return false;for(const x of g){let dmg=MC.damage(x.cells.length);if(player){dmg=Math.round(dmg*(1+(s.grade-1)*.15));s.enemy-=dmg;s.energy[x.color]=Math.min(100,s.energy[x.color]+x.cells.length*8)}else{s.hp-=Math.max(3,Math.round(dmg*.20*(1+(s.level-1)*.06)))}total+=dmg;log((player?'MC · ':'Rival · ')+MC.tier(x.cells.length)+' de '+x.cells.length+' · '+roles[x.color]);}s.board=MC.refill(s.board,g);highlights=[];chain++;g=MC.groups(s.board)}if(g.length){s.board=MC.board();log('Reorganización de la bahía tras la cascada.')}if(!MC.moves(s.board).length){s.board=MC.board();log('Sin jugadas: tablero reorganizado gratis.')}return true}
async function pick(i){if(busy||s.outcome||s.round===3)return;hints=[];if(selected<0){selected=i;draw();return}if(selected===i){selected=-1;draw();return}if(!MC.adjacent(selected,i)){selected=i;status('Elige una pieza que esté justo al lado.');draw();return}const b=MC.swapped(s.board,selected,i);selected=-1;if(!MC.groups(b).length){status('Ese intercambio no forma un match. Prueba otra combinación.');draw();return}busy=true;const token=epoch;s.board=b;status('Tu escuadrón concentra su energía…');if(!await resolve(true,token))return;if(endCheck()){busy=false;save();draw();return}status('La tropa rival prepara su mejor combinación…');draw();await sleep(550);if(token!==epoch)return;let opts=MC.moves(s.board).sort((a,b)=>b.value-a.value);if(opts.length){s.board=MC.swapped(s.board,opts[0].a,opts[0].b);if(!await resolve(false,token))return}endCheck();busy=false;save();status(s.outcome?'Combate terminado.':'Tu turno: combina colores para cargar a tu escuadrón.');draw();}
async function playCard(i){if(busy||s.outcome||s.round!==3)return;const cost=[2,2,3,3,4][i];if(s.reactor<cost)return;busy=true;const token=epoch;s.reactor-=cost;const dmg=Math.round(([25,28,34,38,48][i]+s.energy[i]*.55)*(1+(s.grade-1)*.15));s.energy[i]=0;s.enemy-=dmg;status(roles[i]+' desplegado · '+dmg+' de daño');log(roles[i]+' ataca al jefe · '+dmg+' de daño');draw();await sleep(500);if(token!==epoch)return;if(!endCheck())bossAttack(false);busy=false;save();draw();}
function bossAttack(guard){const dmg=Math.round((16+s.level*2)*(guard?.4:1));s.hp-=dmg;s.reactor=Math.min(10,s.reactor+(guard?4:2));log('El jefe contraataca · '+dmg+' de daño'+(guard?' (defensa)':''));status(guard?'Daño reducido y reactor recuperado. Elige una carta.':'Contraataque: −'+dmg+' de vida. Reactor +2.');endCheck()}
$('guard').onclick=()=>{if(busy||s.outcome||s.round!==3)return;bossAttack(true);save();draw()};
function startRound(){s.outcome=null;selected=-1;s.board=MC.board();s.enemyMax=Math.round(([90,140,190,340][s.round])*(1+(s.level-1)*.18));s.enemy=s.enemyMax;if(s.round===3)s.reactor=6;status(s.round===3?'Despliega tus cartas. La energía de cada soldado potencia su ataque.':'Tu turno: intercambia piezas vecinas para formar un match.');save();draw()}
$('continue').onclick=()=>{const o=s.outcome;if(!o||busy)return;if(o==='round')s.round++;else{if(o==='level')s.level++;s.round=0;s.hp=maxHP();s.energy=[0,0,0,0,0]}startRound()};
$('hint').onclick=()=>{if(busy||s.outcome)return;const move=MC.moves(s.board).sort((a,b)=>b.value-a.value)[0];if(move){hints=[move.a,move.b];selected=-1;status('Intercambia las dos piezas iluminadas.');draw()}};
$('upgrade').onclick=()=>{if($('upgrade').disabled)return;s.evo-=100;s.grade++;s.hp=Math.min(maxHP(),s.hp+60);log('Equipo mejorado al grado '+s.grade+' · +60 vida y +15% poder');save();draw()};
$('restart').onclick=()=>{if(!confirm(MCI18N.text('¿Reiniciar toda la campaña? Se perderán puntos, mejoras y niveles.')))return;epoch++;busy=false;selected=-1;highlights=[];hints=[];feed=[];s=fresh();save();status('Nueva campaña iniciada. Tu escuadrón está listo.');log('Nivel 1 · rumbo al sector Orión.');draw()};
$('helpButton').onclick=()=>$('help').showModal();$('closeHelp').onclick=()=>$('help').close();$('ready').onclick=()=>$('help').close();
if(MC.groups(s.board).length||!MC.moves(s.board).length)s.board=MC.board();log('Escuadrón conectado · nivel '+s.level+'.');draw();save();
